const svg = document.getElementById('lc-svg');
const out = document.getElementById('lc-out');
const W = 160;
// axes (t up = -y, x right)
function build(){
  while(svg.firstChild) svg.removeChild(svg.firstChild);
  // light-cone region (|x| <= |t|)
  const cone = SVG('path',{
    d:`M0,0 L-${W},-${W} L${W},-${W} Z M0,0 L-${W},${W} L${W},${W} Z`,
    fill:'rgba(255,216,102,0.10)', stroke:'var(--yellow)', 'stroke-width':1
  });
  svg.appendChild(cone);
  // null lines
  svg.appendChild(SVG('line',{x1:-W,y1:-W,x2:W,y2:W,stroke:'var(--yellow)','stroke-dasharray':'4 3','stroke-width':1}));
  svg.appendChild(SVG('line',{x1:-W,y1:W,x2:W,y2:-W,stroke:'var(--yellow)','stroke-dasharray':'4 3','stroke-width':1}));
  // axes
  svg.appendChild(SVG('line',{x1:-W,y1:0,x2:W,y2:0,stroke:'var(--line)','stroke-width':1}));
  svg.appendChild(SVG('line',{x1:0,y1:-W,x2:0,y2:W,stroke:'var(--line)','stroke-width':1}));
  const tx = SVG('text',{x:6,y:-W+12,'font-size':12,fill:'var(--mute)'}); tx.textContent='t (future)'; svg.appendChild(tx);
  const xx = SVG('text',{x:W-12,y:-6,'font-size':12,fill:'var(--mute)','text-anchor':'end'}); xx.textContent='x'; svg.appendChild(xx);
}
let vx = 40, vt = -100;  // (x, t) with t up means y = -t
function draw(){
  build();
  const x2 = vx, y2 = -vt;
  const inner = vx*vx - vt*vt; // = g(v,v) with c=1
  let kind, color;
  if(Math.abs(inner) < 30){ kind='lightlike (null)'; color='var(--yellow)'; }
  else if(inner < 0){ kind = (vt>0 ? 'timelike (future)' : 'timelike (past)'); color='var(--cyan)'; }
  else { kind='spacelike'; color='var(--pink)'; }
  // vector
  ensureArrow(svg,'lc-arr',color);
  svg.appendChild(SVG('line',{x1:0,y1:0,x2,y2,stroke:color,'stroke-width':2.4,'marker-end':'url(#lc-arr)'}));
  // draggable head
  const h = SVG('circle',{cx:x2,cy:y2,r:8,fill:color,stroke:'var(--ink)','stroke-width':1.2,style:'cursor:grab'});
  svg.appendChild(h);
  h.addEventListener('pointerdown', e => {
    e.preventDefault();
    h.style.cursor = 'grabbing';
    // Listen on document, not h — draw() rebuilds the SVG and orphans
    // any handler attached to h, killing the drag mid-gesture.
    const r = svg.getBoundingClientRect();
    function move(ev){
      const sx = (ev.clientX - r.left)/r.width * 320 - 160;
      const sy = (ev.clientY - r.top)/r.height * 320 - 160;
      vx = Math.max(-W+8, Math.min(W-8, sx));
      vt = -Math.max(-W+8, Math.min(W-8, sy));
      draw();
    }
    function up(){
      document.removeEventListener('pointermove', move);
      document.removeEventListener('pointerup', up);
      // h was rebuilt inside draw(), so don't try to re-style it; the
      // newly-rendered handle uses the default cursor:grab from its inline style.
    }
    document.addEventListener('pointermove', move);
    document.addEventListener('pointerup', up, {once:true});
  });
  out.textContent = `v = (Δt=${vt.toFixed(0)}, Δx=${vx.toFixed(0)})    g(v,v) = Δx² − Δt² = ${inner.toFixed(0)}    ⇒  ${kind}`;
}
draw();

const svg=document.getElementById('ee-svg');
const out=document.getElementById('ee-out');
const rho=document.getElementById('ee-rho');
const lam=document.getElementById('ee-lam');
function draw(){
  while(svg.firstChild) svg.removeChild(svg.firstChild);
  const r = parseFloat(rho.value);
  const L = parseFloat(lam.value);
  // model: average sectional curvature ~ ρ + Λ/3
  const K = r + L/3;
  // draw a grid distorted by K
  const N = 9;
  for(let i=-N;i<=N;i++){
    let d='';
    for(let j=-N;j<=N;j++){
      const x = j*16;
      const y = i*16;
      // bend by K
      const bend = K*0.05*(x*x+y*y)/40;
      const yy = y - bend;
      if(j===-N) d += `M${x} ${yy}`; else d += ` L${x} ${yy}`;
    }
    svg.appendChild(SVG('path',{d,fill:'none',stroke:K>0?'var(--cyan)':(K<0?'var(--pink)':'var(--mute)'),'stroke-width':0.8,opacity:0.7}));
  }
  for(let j=-N;j<=N;j++){
    let d='';
    for(let i=-N;i<=N;i++){
      const x=j*16,y=i*16;
      const bend=K*0.05*(x*x+y*y)/40;
      const yy=y-bend;
      if(i===-N) d+=`M${x} ${yy}`; else d+=` L${x} ${yy}`;
    }
    svg.appendChild(SVG('path',{d,fill:'none',stroke:K>0?'var(--cyan)':(K<0?'var(--pink)':'var(--mute)'),'stroke-width':0.8,opacity:0.7}));
  }
  out.textContent = `ρ = ${r.toFixed(2)}    Λ = ${L.toFixed(2)}    sketch K ≈ ρ + Λ/3 = ${K.toFixed(2)}    ${K>0.05?'positive (closing geodesics)':K<-0.05?'negative (diverging geodesics)':'flat'}`;
}
rho.addEventListener('input',draw);
lam.addEventListener('input',draw);
draw();

const svg=document.getElementById('sch-svg');
const out=document.getElementById('sch-out');
const sl=document.getElementById('sch-r');
function build(){
  while(svg.firstChild) svg.removeChild(svg.firstChild);
  // r-axis
  svg.appendChild(SVG('line',{x1:-200,y1:90,x2:200,y2:90,stroke:'var(--line)'}));
  // horizon at r = 2M (mapped to x = -100)
  svg.appendChild(SVG('line',{x1:-100,y1:-110,x2:-100,y2:90,stroke:'var(--pink)','stroke-dasharray':'3 3','stroke-width':1.2}));
  const t = SVG('text',{x:-100,y:-95,'text-anchor':'middle','font-size':12,fill:'var(--pink)'}); t.textContent='r = 2M (horizon)'; svg.appendChild(t);
  const t2 = SVG('text',{x:200,y:106,'text-anchor':'end','font-size':12,fill:'var(--mute)'}); t2.textContent='r →'; svg.appendChild(t2);
  // place 5 sample cones
  const samples=[0.8,1.4,2.0,3.0,5.0];
  samples.forEach(rm => {
    const x = -100 + (rm-2)*60;
    drawCone(x, 30, rm, 0.5);
  });
  // active cone
  const rm = parseFloat(sl.value);
  const x = -100 + (rm-2)*60;
  drawCone(x, 30, rm, 1.0);
  out.textContent = formatOut(rm);
}
function drawCone(cx, cy, rm, alpha){
  // null slope = ±(1 - 2M/r) inside r>2M; reverses inside
  const f = 1 - 2/rm;
  const slope = f; // dt/dr along null in (t,r*) coords; we plot dt vs dr
  const h = 28;
  const dx = h * (slope > 0 ? 1 : -1);
  const dr = Math.min(0.9, Math.abs(slope)) * h * (slope < 0 ? 1 : 1);
  let color;
  if(rm < 2) color='var(--pink)';
  else if(Math.abs(rm-2)<0.05) color='var(--yellow)';
  else color='var(--cyan)';
  // simple cone: outward null + inward null
  // outside horizon: both null directions point outward in t (future = up)
  // inside: both point toward decreasing r (collapse toward singularity)
  const out_dx = h*0.7, out_dt = -h*0.9;
  const in_dx = -h*0.7, in_dt = -h*0.9;
  if(rm < 2){
    // tip cones: future light cones point toward smaller r
    svg.appendChild(SVG('path',{
      d:`M${cx} ${cy} L${cx-h*0.9} ${cy-h*0.7} L${cx-h*0.9} ${cy+h*0.7} Z`,
      fill:`color-mix(in srgb, ${color} 18%, transparent)`,stroke:color,'stroke-width':1.4,opacity:alpha
    }));
  } else {
    svg.appendChild(SVG('path',{
      d:`M${cx} ${cy} L${cx+out_dx} ${cy+out_dt} L${cx+in_dx} ${cy+in_dt} Z`,
      fill:`color-mix(in srgb, ${color} 18%, transparent)`,stroke:color,'stroke-width':1.4,opacity:alpha
    }));
  }
  // worldline tick
  svg.appendChild(SVG('circle',{cx,cy,r:2.5,fill:color,opacity:alpha}));
}
function formatOut(rm){
  const f = 1 - 2/rm;
  if(rm < 2) return `r/M = ${rm.toFixed(2)} < 2  ⇒  inside horizon. g_tt = ${(-f).toFixed(2)} (sign flip!), light cones point toward singularity.`;
  if(Math.abs(rm-2) < 0.05) return `r/M ≈ 2  ⇒  on the event horizon. g_tt → 0, cones tilt to 45°.`;
  return `r/M = ${rm.toFixed(2)}  ⇒  outside horizon. g_tt = ${(-f).toFixed(2)}, light cones open in usual orientation.`;
}
sl.addEventListener('input',build);
build();

const svg=document.getElementById('kerr-svg');
const out=document.getElementById('kerr-out');
const sl=document.getElementById('kerr-a');
function build(){
  while(svg.firstChild) svg.removeChild(svg.firstChild);
  const a = parseFloat(sl.value);
  const M = 1, scale = 50;
  // singularity ring at r=0, θ=π/2: x^2 + y^2 = a^2 in equator
  // we render in (x = r sinθ, y = r cosθ) meridional plane
  // event horizon radius (constant in r)
  const rPlus = M + Math.sqrt(Math.max(0, M*M - a*a));
  const rMinus = M - Math.sqrt(Math.max(0, M*M - a*a));
  // stationary limit: r_SL(θ) = M + √(M² - a² cos²θ)
  // ergosphere is between rPlus and rSL
  // spin axis (vertical)
  svg.appendChild(SVG('line',{x1:0,y1:-150,x2:0,y2:150,stroke:'var(--line)','stroke-dasharray':'3 3'}));
  // ergosphere region
  let ergoPath = '';
  const steps = 120;
  for(let i=0;i<=steps;i++){
    const th = i/steps * Math.PI;
    const rSL = M + Math.sqrt(Math.max(0, M*M - a*a*Math.cos(th)*Math.cos(th)));
    const x = rSL * Math.sin(th) * scale;
    const y = rSL * Math.cos(th) * scale;
    ergoPath += (i===0?'M':'L') + x + ' ' + y;
  }
  for(let i=steps;i>=0;i--){
    const th = i/steps * Math.PI;
    const x = -(M + Math.sqrt(Math.max(0, M*M - a*a*Math.cos(th)*Math.cos(th)))) * Math.sin(th) * scale;
    const y = (M + Math.sqrt(Math.max(0, M*M - a*a*Math.cos(th)*Math.cos(th)))) * Math.cos(th) * scale;
    ergoPath += 'L' + x + ' ' + y;
  }
  ergoPath += 'Z';
  svg.appendChild(SVG('path',{d:ergoPath,fill:'rgba(224,122,95,0.18)',stroke:'var(--pink)','stroke-width':1.2}));
  // outer horizon (sphere of radius rPlus, both sides)
  svg.appendChild(SVG('ellipse',{cx:0,cy:0,rx:rPlus*scale,ry:rPlus*scale,fill:'rgba(0,0,0,0.55)',stroke:'var(--yellow)','stroke-width':1.5}));
  // inner horizon
  if(rMinus > 0){
    svg.appendChild(SVG('ellipse',{cx:0,cy:0,rx:rMinus*scale,ry:rMinus*scale,fill:'none',stroke:'var(--cyan)','stroke-width':1,'stroke-dasharray':'3 3'}));
  }
  // ring singularity (equatorial line through origin extending to ±a)
  svg.appendChild(SVG('line',{x1:-a*scale,y1:0,x2:a*scale,y2:0,stroke:'var(--violet)','stroke-width':2.5}));
  // labels
  const t1 = SVG('text',{x:0,y:-rPlus*scale-8,'text-anchor':'middle','font-size':12,fill:'var(--yellow)'}); t1.textContent=`r₊ = ${rPlus.toFixed(2)} M`; svg.appendChild(t1);
  const t2 = SVG('text',{x:130,y:140,'text-anchor':'end','font-size':12,fill:'var(--pink)'}); t2.textContent='ergosphere'; svg.appendChild(t2);
  const t3 = SVG('text',{x:130,y:-130,'text-anchor':'end','font-size':12,fill:'var(--mute)'}); t3.textContent='spin axis ↑'; svg.appendChild(t3);
  if(a >= 0.999) out.textContent = `a/M = ${a.toFixed(2)}  ⇒  EXTREMAL Kerr. r₊ = r− = M; horizons merge. Beyond a/M = 1 the singularity becomes naked.`;
  else if(a < 0.01) out.textContent = `a/M ≈ 0  ⇒  Schwarzschild limit: r₊ = 2M, ergosphere collapses to the horizon.`;
  else out.textContent = `a/M = ${a.toFixed(2)}    r₊ = ${rPlus.toFixed(2)} M    r− = ${rMinus.toFixed(2)} M    ergosphere thickness on equator: ${(M+Math.sqrt(M*M-a*a*0)-rPlus).toFixed(2)} M`;
}
sl.addEventListener('input',build);
build();

const svg=document.getElementById('frw-svg');
const out=document.getElementById('frw-out');
const sl=document.getElementById('frw-l');
function build(){
  while(svg.firstChild) svg.removeChild(svg.firstChild);
  const OL = parseFloat(sl.value);
  const Om = 1 - OL;
  // axes
  svg.appendChild(SVG('line',{x1:0,y1:0,x2:340,y2:0,stroke:'var(--line)'}));
  svg.appendChild(SVG('line',{x1:0,y1:-150,x2:0,y2:0,stroke:'var(--line)'}));
  const xt = SVG('text',{x:325,y:14,'font-size':12,fill:'var(--mute)','text-anchor':'end'}); xt.textContent='t/H₀⁻¹'; svg.appendChild(xt);
  const yt = SVG('text',{x:6,y:-145,'font-size':12,fill:'var(--mute)'}); yt.textContent='a(t)/a₀'; svg.appendChild(yt);
  // gridlines
  for(let i=1;i<=4;i++){
    svg.appendChild(SVG('line',{x1:0,y1:-i*30,x2:340,y2:-i*30,stroke:'var(--line)','stroke-width':0.5,opacity:0.5}));
  }
  // integrate Friedmann: (a'/a)² = Ωm/a³ + ΩΛ , flat case
  // dt = da / [a · √(Ωm/a³ + ΩΛ)]
  const pts = [];
  let a = 0.01;
  let t = 0;
  const da = 0.005;
  while(a < 5 && t < 4){
    const Hsq = Om/(a*a*a) + OL;
    const dt = da / (a * Math.sqrt(Hsq));
    t += dt;
    a += da;
    pts.push([t, a]);
  }
  // also rewind
  let a2 = 0.01, t2 = 0;
  const back=[];
  while(a2 > 0.001 && t2 > -2){
    const Hsq = Om/(a2*a2*a2) + OL;
    const dt = da / (a2 * Math.sqrt(Hsq));
    t2 -= dt;
    a2 -= da;
    back.unshift([t2, a2]);
  }
  const all = back.concat(pts);
  // shift so that a=1 at t=0 (today)
  let tNow = 0;
  for(const p of all) if(Math.abs(p[1]-1) < 0.05) { tNow = p[0]; break; }
  let d='';
  all.forEach((p,i)=>{
    const X = (p[0] - tNow + 1) * 70;
    const Y = -p[1] * 50;
    if(X<0 || X>340 || Y<-155) return;
    d += (d===''?'M':' L') + X.toFixed(1) + ' ' + Y.toFixed(1);
  });
  svg.appendChild(SVG('path',{d,fill:'none',stroke:'var(--cyan)','stroke-width':2}));
  // mark "now"
  svg.appendChild(SVG('line',{x1:70,y1:-50,x2:70,y2:0,stroke:'var(--yellow)','stroke-dasharray':'3 3'}));
  const tn = SVG('text',{x:70,y:14,'text-anchor':'middle','font-size':11,fill:'var(--yellow)'}); tn.textContent='now (a=1)'; svg.appendChild(tn);
  // verdict
  let verdict;
  if(OL > 0.6) verdict = 'accelerating (Λ-dominated)';
  else if(OL > 0.3) verdict = 'transitioning to acceleration';
  else verdict = 'decelerating (matter-dominated)';
  out.textContent = `Ω_m = ${Om.toFixed(2)}    Ω_Λ = ${OL.toFixed(2)}    expansion ${verdict}`;
}
sl.addEventListener('input',build);
build();

const svg=document.getElementById('gw-svg');
const out=document.getElementById('gw-out');
const plus=document.getElementById('gw-plus');
const cross=document.getElementById('gw-cross');
const play=document.getElementById('gw-play');
const hsl=document.getElementById('gw-h');
let mode='plus';
let playing=false;
let phase=0;
let raf=null;
plus.addEventListener('click',()=>{mode='plus';plus.classList.add('active');cross.classList.remove('active');draw();});
cross.addEventListener('click',()=>{mode='cross';cross.classList.add('active');plus.classList.remove('active');draw();});
play.addEventListener('click',()=>{
  playing=!playing;
  play.textContent = playing?'⏸ pause':'▶ play';
  if(playing) loop();
  else if(raf){ cancelAnimationFrame(raf); raf=null; }
});
function loop(){
  phase += 0.04;
  draw();
  raf = requestAnimationFrame(loop);
}
function draw(){
  while(svg.firstChild) svg.removeChild(svg.firstChild);
  const h = parseFloat(hsl.value) * Math.cos(phase);
  // axes
  svg.appendChild(SVG('line',{x1:-100,y1:0,x2:100,y2:0,stroke:'var(--line)','stroke-dasharray':'2 3'}));
  svg.appendChild(SVG('line',{x1:0,y1:-100,x2:0,y2:100,stroke:'var(--line)','stroke-dasharray':'2 3'}));
  // unperturbed circle
  svg.appendChild(SVG('circle',{cx:0,cy:0,r:80,fill:'none',stroke:'var(--mute)','stroke-dasharray':'3 3','stroke-width':0.8,opacity:0.5}));
  // 12 test masses
  const N=12;
  const r0=80;
  for(let i=0;i<N;i++){
    const th = i*2*Math.PI/N;
    let x = r0*Math.cos(th);
    let y = r0*Math.sin(th);
    if(mode==='plus'){
      x *= (1 + h*0.5);
      y *= (1 - h*0.5);
    } else {
      // cross mode = plus mode rotated 45° → mixes x and y
      const cx = (x+y)*0.5*(1+h*0.5) + (x-y)*0.5*(1-h*0.5);
      const cy = (x+y)*0.5*(1+h*0.5) - (x-y)*0.5*(1-h*0.5);
      x = cx; y = cy;
    }
    svg.appendChild(SVG('circle',{cx:x,cy:y,r:5,fill:mode==='plus'?'var(--cyan)':'var(--violet)','stroke':'var(--ink)','stroke-width':0.8}));
  }
  // arrows showing direction of stretch
  if(mode==='plus'){
    svg.appendChild(SVG('text',{x:108,y:5,'font-size':11,fill:'var(--cyan)'})).textContent = h>0?'→ stretch':'← squeeze';
    svg.appendChild(SVG('text',{x:0,y:-108,'text-anchor':'middle','font-size':11,fill:'var(--cyan)'})).textContent = h>0?'↓ squeeze':'↑ stretch';
  }
  out.textContent = `mode: ${mode}    h(t) = ${h.toFixed(3)}    LIGO-scale strain h ≈ 10⁻²¹ over 4 km arms displaces mirrors by ~ 10⁻¹⁸ m.`;
}
draw();
